BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT105-S1-Q13$batch12$ AND q.stimulus=$batch12$If an artist receives a public subsidy to support work on a specific project—e.g., making a film—and if this project then proves successful enough to allow the artist to repay the subsidy, is the artist morally obliged to do so? The answer is clearly yes, since the money returned to the agency distributing the subsidies will be welcome as a source of support for other artists deserving of public subsidies.$batch12$ AND q.prompt=$batch12$The passage tries to establish an artist's obligation by arguing that$batch12$ AND q.correct_choice=$batch12$B$batch12$) THEN RAISE EXCEPTION 'Question changed: PT105-S1-Q13'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT105-S1-Q13$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT105-S1-Q13'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT105-S1-Q13$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$An artist whose subsidized project succeeds is morally obliged to repay the subsidy.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$The returned money will support other deserving artists.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$The reason given looks forward to other artists. Repaying lets them get the same kind of support this artist got.$batch12$), (3, $batch12$Goal$batch12$, $batch12$Repaying would let others receive a benefit like the one this artist received.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT105-S1-Q13$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
